  j constant jsonb := $j$[
{"id":"ff3280a4-5b38-45b7-9e9e-2c36b497be08","recipe_group_id":"bfeac8bb-feaa-45be-b11f-dc89564a535d","language":"es","slug":"receta-trucha-al-ajillo-con-limon","public_path":"/receta-trucha-al-ajillo-con-limon","source_url":"https://manualdecocina.com/receta-trucha-al-ajillo-con-limon/","title":"Trucha al ajillo con limón","excerpt":"Filetes de trucha dorados en sartén y bañados con una salsa de ajo y limón hecha en la misma sartén. Rinde 4 raciones y se prepara en 20 minutos.","summary":"La trucha al ajillo con limón es un plato rápido: filetes secos y sazonados que se doran en aceite de oliva y se terminan con una salsa de ajo, jugo y ralladura de limón preparada en la misma sartén.\n\nSe sirve de inmediato con perejil fresco, acompañada de arroz, verduras o ensalada. Rinde 4 raciones y está lista en unos 20 minutos.","category":"Platos principales","difficulty":"Fácil","course":"Plato principal","cuisine":"Pescados","prep_time_minutes":10,"cook_time_minutes":10,"total_time_minutes":20,"servings":4,"keywords":["trucha al ajillo con limón","trucha al ajillo","receta de trucha","filetes de trucha","pescado con limón y ajo","receta rápida de pescado"],"ingredients":[{"name":"filetes de trucha (4 filetes de unos 150 g)","amount":"600","unit":"g","group":"Para el pescado"},{"name":"ajo, picado","amount":"4","unit":"dientes","group":"Para la salsa"},{"name":"limones (jugo y ralladura)","amount":"2","unit":"unidad","group":"Para la salsa"},{"name":"aceite de oliva","amount":"30","unit":"ml","group":"Para el pescado"},{"name":"sal","amount":"3","unit":"g","group":"Para el pescado"},{"name":"pimienta negra","amount":"1","unit":"g","group":"Para el pescado"},{"name":"perejil fresco, picado","amount":"10","unit":"g","group":"Para terminar"}],"steps":[{"title":"Seca y sazona la trucha","content":"Seca 4 filetes de trucha (unos 150 g cada uno) con papel de cocina y sazónalos con 3 g de sal y 1 g de pimienta negra.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-01.webp","image_alt":"Trucha al ajillo con limón: Seca y sazona la trucha"},{"title":"Prepara la mezcla de ajo y limón","content":"Mezcla el jugo y la ralladura de 2 limones con 4 dientes de ajo picados.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-02.webp","image_alt":"Trucha al ajillo con limón: Prepara la mezcla de ajo y limón"},{"title":"Calienta el aceite","content":"Calienta 2 cucharadas de aceite de oliva (30 ml) en una sartén amplia a fuego medio-alto.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-03.webp","image_alt":"Trucha al ajillo con limón: Calienta el aceite"},{"title":"Cocina la trucha","content":"Cocina los filetes unos 3–4 minutos por cada lado, según el grosor, hasta que estén opacos y se desmenucen fácilmente.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-04.webp","image_alt":"Trucha al ajillo con limón: Cocina la trucha"},{"title":"Retira el pescado","content":"Pasa la trucha a un plato y deja la sartén al fuego medio.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-05.webp","image_alt":"Trucha al ajillo con limón: Retira el pescado"},{"title":"Haz la salsa","content":"Añade a la sartén la mezcla de ajo y limón y cocina 1–2 minutos, sin dejar que el ajo se queme.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-06.webp","image_alt":"Trucha al ajillo con limón: Haz la salsa"},{"title":"Baña y termina","content":"Vierte la salsa sobre la trucha y termina con 10 g de perejil fresco picado.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-07.webp","image_alt":"Trucha al ajillo con limón: Baña y termina"},{"title":"Sirve","content":"Sirve de inmediato con arroz, verduras o ensalada.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-08.webp","image_alt":"Trucha al ajillo con limón: Sirve"}],"image_url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","gallery":[{"url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","alt":"Trucha al ajillo con limón"}],"notes":"Seca bien el pescado antes de sazonarlo para que se dore en lugar de cocerse al vapor. No dejes que el ajo se oscurezca: un ajo quemado amarga la salsa; si la sartén está muy caliente, bájala antes de añadir la mezcla. Los pesos de sal y pimienta son orientativos; ajusta al gusto. Contiene pescado; revisa los filetes con los dedos por si quedan espinas.","nutrition":{"calories":281,"protein_g":30.3,"carbs_g":3,"fat_g":16.1,"sodium_mg":371,"serving_size":"1 filete con salsa (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4. Se usan 600 g de trucha, 12 g de ajo (4 dientes), 62 g de jugo y 6 g de ralladura de 2 limones, 27 g de aceite (30 ml), 3 g de sal, 1 g de pimienta y 10 g de perejil.","note":"Estimación por ración; el valor de sodio incluye los 3 g de sal indicados y el aceite se cuenta completo aunque parte quede en la sartén. Se usa el valor USDA de la trucha arcoíris de cultivo; la trucha silvestre tiene menos grasa.","inputs":[{"fdc_id":"175167","description":"Fish, trout, rainbow, farmed, raw","grams":600,"per100":{"calories":141,"protein_g":19.94,"carbs_g":0,"fat_g":6.18,"saturated_fat_g":1.584,"fiber_g":0,"sodium_mg":52}},{"fdc_id":"169230","description":"Garlic, raw","grams":12,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"167747","description":"Lemon juice, raw","grams":62,"per100":{"calories":22,"protein_g":0.35,"carbs_g":6.9,"fat_g":0.24,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1}},{"fdc_id":"168155","description":"Lemon peel, raw","grams":6,"per100":{"calories":47,"protein_g":1.5,"carbs_g":16,"fat_g":0.3,"saturated_fat_g":0.039,"fiber_g":10.6,"sodium_mg":6}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking","grams":27,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.808,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"173468","description":"Salt, table","grams":3,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}},{"fdc_id":"170931","description":"Spices, pepper, black","grams":1,"per100":{"calories":251,"protein_g":10.39,"carbs_g":63.95,"fat_g":3.26,"saturated_fat_g":1.392,"fiber_g":25.3,"sodium_mg":20}},{"fdc_id":"170416","description":"Parsley, fresh","grams":10,"per100":{"calories":36,"protein_g":2.97,"carbs_g":6.33,"fat_g":0.79,"saturated_fat_g":0.132,"fiber_g":3.3,"sodium_mg":56}}]},"seo":{"title":"Trucha al ajillo con limón en sartén | Manual de Cocina","description":"Trucha al ajillo con limón: filetes dorados en sartén con salsa de ajo y limón. 4 raciones, lista en 20 minutos. Paso a paso.","image_variants":["/recetas/receta-trucha-al-ajillo-con-limon/portada-1x1.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-4x3.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-16x9.webp"],"faq":[{"q":"¿Cuánto tiempo se cocina la trucha en la sartén?","a":"Unos 3–4 minutos por cada lado, según el grosor, hasta que el filete esté opaco y se desmenuce fácilmente."},{"q":"¿Cómo evito que se queme el ajo?","a":"Prepara la salsa con la sartén a fuego medio y cocina la mezcla de ajo y limón solo 1–2 minutos. Un ajo oscuro amarga la salsa."},{"q":"¿Con qué se acompaña la trucha al ajillo?","a":"Con arroz, verduras o ensalada. Se sirve de inmediato, con la salsa por encima y perejil fresco."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"3e9fb5bf-c872-5848-8a69-f1e4aca3c35c","recipe_group_id":"bfeac8bb-feaa-45be-b11f-dc89564a535d","language":"de","slug":"forelle-mit-knoblauch-und-zitrone","public_path":"/de/forelle-mit-knoblauch-und-zitrone","source_url":null,"title":"Forelle mit Knoblauch und Zitrone","excerpt":"In der Pfanne gebratene Forellenfilets mit einer Knoblauch-Zitronen-Sauce aus derselben Pfanne. Ergibt 4 Portionen und ist in 20 Minuten fertig.","summary":"Forelle mit Knoblauch und Zitrone ist ein schnelles Gericht: Trockene, gewürzte Filets werden in Olivenöl goldbraun gebraten und mit einer Sauce aus Knoblauch, Zitronensaft und Zitronenschale aus derselben Pfanne vollendet.\n\nSie wird sofort mit frischer Petersilie serviert, dazu passen Reis, Gemüse oder Salat. Ergibt 4 Portionen und ist in etwa 20 Minuten fertig.","category":"Hauptgerichte","difficulty":"Einfach","course":"Hauptgericht","cuisine":"Fisch","prep_time_minutes":10,"cook_time_minutes":10,"total_time_minutes":20,"servings":4,"keywords":["Forelle mit Knoblauch und Zitrone","Forelle Knoblauch","Forellenfilet Rezept","Forellenfilets braten","Fisch mit Zitrone und Knoblauch","schnelles Fischrezept"],"ingredients":[{"name":"Forellenfilets (4 Filets à etwa 150 g)","amount":"600","unit":"g","group":"Für den Fisch"},{"name":"Knoblauch, gehackt","amount":"4","unit":"Zehen","group":"Für die Sauce"},{"name":"Zitronen (Saft und Schale)","amount":"2","unit":"Stück","group":"Für die Sauce"},{"name":"Olivenöl","amount":"30","unit":"ml","group":"Für den Fisch"},{"name":"Salz","amount":"3","unit":"g","group":"Für den Fisch"},{"name":"schwarzer Pfeffer","amount":"1","unit":"g","group":"Für den Fisch"},{"name":"frische Petersilie, gehackt","amount":"10","unit":"g","group":"Zum Vollenden"}],"steps":[{"title":"Forelle trocknen und würzen","content":"4 Forellenfilets (je etwa 150 g) mit Küchenpapier trocken tupfen und mit 3 g Salz und 1 g schwarzem Pfeffer würzen.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-01.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Forelle trocknen und würzen"},{"title":"Knoblauch-Zitronen-Mischung zubereiten","content":"Saft und Schale von 2 Zitronen mit 4 gehackten Knoblauchzehen vermischen.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-02.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Knoblauch-Zitronen-Mischung zubereiten"},{"title":"Öl erhitzen","content":"2 Esslöffel Olivenöl (30 ml) in einer großen Pfanne bei mittlerer bis hoher Hitze erhitzen.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-03.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Öl erhitzen"},{"title":"Forelle braten","content":"Die Filets je nach Dicke etwa 3–4 Minuten pro Seite braten, bis sie undurchsichtig sind und sich leicht zerteilen lassen.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-04.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Forelle braten"},{"title":"Fisch herausnehmen","content":"Die Forelle auf einen Teller legen und die Pfanne bei mittlerer Hitze auf dem Herd lassen.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-05.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Fisch herausnehmen"},{"title":"Sauce zubereiten","content":"Die Knoblauch-Zitronen-Mischung in die Pfanne geben und 1–2 Minuten garen, ohne dass der Knoblauch verbrennt.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-06.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Sauce zubereiten"},{"title":"Übergießen und vollenden","content":"Die Sauce über die Forelle gießen und mit 10 g gehackter frischer Petersilie vollenden.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-07.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Übergießen und vollenden"},{"title":"Servieren","content":"Sofort mit Reis, Gemüse oder Salat servieren.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-08.webp","image_alt":"Forelle mit Knoblauch und Zitrone: Servieren"}],"image_url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","gallery":[{"url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","alt":"Forelle mit Knoblauch und Zitrone"}],"notes":"Den Fisch vor dem Würzen gut trocknen, damit er brät, statt zu dämpfen. Den Knoblauch nicht dunkel werden lassen: Verbrannter Knoblauch macht die Sauce bitter; ist die Pfanne zu heiß, vorher die Hitze reduzieren. Die Mengen für Salz und Pfeffer sind Richtwerte; nach Geschmack anpassen. Enthält Fisch; die Filets mit den Fingern auf Gräten prüfen.","nutrition":{"calories":281,"protein_g":30.3,"carbs_g":3,"fat_g":16.1,"sodium_mg":371,"serving_size":"1 Filet mit Sauce (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 geteilt. Verwendet werden 600 g Forelle, 12 g Knoblauch (4 Zehen), 62 g Saft und 6 g Schale von 2 Zitronen, 27 g Öl (30 ml), 3 g Salz, 1 g Pfeffer und 10 g Petersilie.","note":"Schätzung pro Portion; der Natriumwert enthält die angegebenen 3 g Salz, und das Öl wird vollständig gerechnet, auch wenn ein Teil in der Pfanne bleibt. Verwendet wird der USDA-Wert für Zuchtregenbogenforelle; Wildforelle ist magerer."},"seo":{"title":"Forelle mit Knoblauch und Zitrone aus der Pfanne | Manual de Cocina","description":"Forelle mit Knoblauch und Zitrone: goldbraun gebratene Filets mit Knoblauch-Zitronen-Sauce. 4 Portionen, in 20 Minuten fertig. Schritt für Schritt.","image_variants":["/recetas/receta-trucha-al-ajillo-con-limon/portada-1x1.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-4x3.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-16x9.webp"],"faq":[{"q":"Wie lange wird Forelle in der Pfanne gebraten?","a":"Etwa 3–4 Minuten pro Seite, je nach Dicke, bis das Filet undurchsichtig ist und sich leicht zerteilen lässt."},{"q":"Wie verhindere ich, dass der Knoblauch verbrennt?","a":"Die Sauce bei mittlerer Hitze zubereiten und die Knoblauch-Zitronen-Mischung nur 1–2 Minuten garen. Dunkler Knoblauch macht die Sauce bitter."},{"q":"Was passt zu Forelle mit Knoblauch und Zitrone?","a":"Reis, Gemüse oder Salat. Sie wird sofort serviert, mit der Sauce darüber und frischer Petersilie."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"533b182b-0a6e-5b3e-9e43-f3b1228ddb02","recipe_group_id":"bfeac8bb-feaa-45be-b11f-dc89564a535d","language":"en","slug":"lemon-garlic-trout","public_path":"/en/lemon-garlic-trout","source_url":null,"title":"Lemon Garlic Trout","excerpt":"Pan-seared trout fillets finished with a garlic and lemon sauce made in the same pan. Serves 4 and takes 20 minutes.","summary":"Lemon garlic trout is a quick dish: dry, seasoned fillets are seared in olive oil and finished with a sauce of garlic, lemon juice and lemon zest made in the same pan.\n\nServe it right away with fresh parsley, alongside rice, vegetables or a salad. It serves 4 and is ready in about 20 minutes.","category":"Main dishes","difficulty":"Easy","course":"Main course","cuisine":"Fish","prep_time_minutes":10,"cook_time_minutes":10,"total_time_minutes":20,"servings":4,"keywords":["lemon garlic trout","garlic trout","trout fillet recipe","pan-seared trout","fish with lemon and garlic","quick fish recipe"],"ingredients":[{"name":"trout fillets (4 fillets of about 150 g)","amount":"600","unit":"g","group":"For the fish"},{"name":"garlic, minced","amount":"4","unit":"cloves","group":"For the sauce"},{"name":"lemons (juice and zest)","amount":"2","unit":"piece","group":"For the sauce"},{"name":"olive oil","amount":"30","unit":"ml","group":"For the fish"},{"name":"salt","amount":"3","unit":"g","group":"For the fish"},{"name":"black pepper","amount":"1","unit":"g","group":"For the fish"},{"name":"fresh parsley, chopped","amount":"10","unit":"g","group":"To finish"}],"steps":[{"title":"Dry and season the trout","content":"Pat 4 trout fillets (about 150 g each) dry with paper towels and season with 3 g salt and 1 g black pepper.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-01.webp","image_alt":"Lemon Garlic Trout: Dry and season the trout"},{"title":"Make the garlic-lemon mixture","content":"Combine the juice and zest of 2 lemons with 4 minced garlic cloves.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-02.webp","image_alt":"Lemon Garlic Trout: Make the garlic-lemon mixture"},{"title":"Heat the oil","content":"Heat 2 tablespoons olive oil (30 ml) in a large skillet over medium-high heat.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-03.webp","image_alt":"Lemon Garlic Trout: Heat the oil"},{"title":"Cook the trout","content":"Cook the fillets about 3–4 minutes per side, depending on thickness, until opaque and easily flaked.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-04.webp","image_alt":"Lemon Garlic Trout: Cook the trout"},{"title":"Remove the fish","content":"Transfer the trout to a plate and keep the skillet over medium heat.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-05.webp","image_alt":"Lemon Garlic Trout: Remove the fish"},{"title":"Make the sauce","content":"Add the garlic-lemon mixture to the skillet and cook 1–2 minutes, without letting the garlic burn.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-06.webp","image_alt":"Lemon Garlic Trout: Make the sauce"},{"title":"Pour and finish","content":"Pour the sauce over the trout and finish with 10 g chopped fresh parsley.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-07.webp","image_alt":"Lemon Garlic Trout: Pour and finish"},{"title":"Serve","content":"Serve immediately with rice, vegetables or salad.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-08.webp","image_alt":"Lemon Garlic Trout: Serve"}],"image_url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","gallery":[{"url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","alt":"Lemon Garlic Trout"}],"notes":"Dry the fish well before seasoning so it sears instead of steaming. Do not let the garlic darken: burnt garlic makes the sauce bitter; if the pan is very hot, lower the heat before adding the mixture. The salt and pepper weights are guides; adjust to taste. Contains fish; run your fingers over the fillets to check for pin bones.","nutrition":{"calories":281,"protein_g":30.3,"carbs_g":3,"fat_g":16.1,"sodium_mg":371,"serving_size":"1 fillet with sauce (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g multiplied by the ingredient weights and divided by 4. It uses 600 g trout, 12 g garlic (4 cloves), 62 g juice and 6 g zest from 2 lemons, 27 g oil (30 ml), 3 g salt, 1 g pepper and 10 g parsley.","note":"Estimate per serving; the sodium value includes the 3 g of salt listed, and all the oil is counted even though some stays in the pan. The USDA value for farmed rainbow trout is used; wild trout is leaner."},"seo":{"title":"Lemon garlic trout in a skillet | Manual de Cocina","description":"Lemon garlic trout: pan-seared fillets with a garlic and lemon sauce. Serves 4, ready in 20 minutes. Step by step.","image_variants":["/recetas/receta-trucha-al-ajillo-con-limon/portada-1x1.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-4x3.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-16x9.webp"],"faq":[{"q":"How long do you cook trout in a skillet?","a":"About 3–4 minutes per side, depending on thickness, until the fillet is opaque and flakes easily."},{"q":"How do I keep the garlic from burning?","a":"Make the sauce over medium heat and cook the garlic-lemon mixture only 1–2 minutes. Dark garlic makes the sauce bitter."},{"q":"What do you serve with lemon garlic trout?","a":"Rice, vegetables or a salad. Serve it right away with the sauce on top and fresh parsley."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"4f42fe36-6f99-5e22-86f7-c132ecdf5c3e","recipe_group_id":"bfeac8bb-feaa-45be-b11f-dc89564a535d","language":"fr","slug":"truite-a-lail-et-au-citron","public_path":"/fr/truite-a-lail-et-au-citron","source_url":null,"title":"Truite à l’ail et au citron","excerpt":"Filets de truite dorés à la poêle, nappés d’une sauce à l’ail et au citron préparée dans la même poêle. Pour 4 personnes, prête en 20 minutes.","summary":"La truite à l’ail et au citron est un plat rapide : des filets secs et assaisonnés sont dorés dans l’huile d’olive, puis terminés avec une sauce à l’ail, au jus et au zeste de citron préparée dans la même poêle.\n\nOn la sert aussitôt avec du persil frais, accompagnée de riz, de légumes ou de salade. Pour 4 personnes, prête en 20 minutes environ.","category":"Plats principaux","difficulty":"Facile","course":"Plat principal","cuisine":"Poissons","prep_time_minutes":10,"cook_time_minutes":10,"total_time_minutes":20,"servings":4,"keywords":["truite à l’ail et au citron","truite à l’ail","recette de truite","filets de truite","poisson au citron et à l’ail","recette rapide de poisson"],"ingredients":[{"name":"filets de truite (4 filets d’environ 150 g)","amount":"600","unit":"g","group":"Pour le poisson"},{"name":"ail, haché","amount":"4","unit":"gousses","group":"Pour la sauce"},{"name":"citrons (jus et zeste)","amount":"2","unit":"pièce","group":"Pour la sauce"},{"name":"huile d’olive","amount":"30","unit":"ml","group":"Pour le poisson"},{"name":"sel","amount":"3","unit":"g","group":"Pour le poisson"},{"name":"poivre noir","amount":"1","unit":"g","group":"Pour le poisson"},{"name":"persil frais, haché","amount":"10","unit":"g","group":"Pour finir"}],"steps":[{"title":"Sécher et assaisonner la truite","content":"Éponger 4 filets de truite (environ 150 g chacun) avec du papier absorbant et les assaisonner avec 3 g de sel et 1 g de poivre noir.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-01.webp","image_alt":"Truite à l’ail et au citron: Sécher et assaisonner la truite"},{"title":"Préparer le mélange ail-citron","content":"Mélanger le jus et le zeste de 2 citrons avec 4 gousses d’ail hachées.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-02.webp","image_alt":"Truite à l’ail et au citron: Préparer le mélange ail-citron"},{"title":"Chauffer l’huile","content":"Chauffer 2 cuillères à soupe d’huile d’olive (30 ml) dans une grande poêle à feu moyen-vif.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-03.webp","image_alt":"Truite à l’ail et au citron: Chauffer l’huile"},{"title":"Cuire la truite","content":"Cuire les filets environ 3 à 4 minutes de chaque côté, selon l’épaisseur, jusqu’à ce qu’ils soient opaques et s’effeuillent facilement.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-04.webp","image_alt":"Truite à l’ail et au citron: Cuire la truite"},{"title":"Retirer le poisson","content":"Transférer la truite sur une assiette et laisser la poêle sur feu moyen.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-05.webp","image_alt":"Truite à l’ail et au citron: Retirer le poisson"},{"title":"Faire la sauce","content":"Ajouter le mélange ail-citron dans la poêle et cuire 1 à 2 minutes, sans laisser brûler l’ail.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-06.webp","image_alt":"Truite à l’ail et au citron: Faire la sauce"},{"title":"Napper et finir","content":"Verser la sauce sur la truite et terminer avec 10 g de persil frais haché.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-07.webp","image_alt":"Truite à l’ail et au citron: Napper et finir"},{"title":"Servir","content":"Servir aussitôt avec du riz, des légumes ou de la salade.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-08.webp","image_alt":"Truite à l’ail et au citron: Servir"}],"image_url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","gallery":[{"url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","alt":"Truite à l’ail et au citron"}],"notes":"Séchez bien le poisson avant de l’assaisonner pour qu’il dore au lieu de cuire à la vapeur. Ne laissez pas l’ail foncer : un ail brûlé rend la sauce amère ; si la poêle est très chaude, baissez le feu avant d’ajouter le mélange. Les poids de sel et de poivre sont indicatifs ; ajustez selon votre goût. Contient du poisson ; passez les doigts sur les filets pour repérer les arêtes.","nutrition":{"calories":281,"protein_g":30.3,"carbs_g":3,"fat_g":16.1,"sodium_mg":371,"serving_size":"1 filet avec sauce (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4. Sont utilisés 600 g de truite, 12 g d’ail (4 gousses), 62 g de jus et 6 g de zeste de 2 citrons, 27 g d’huile (30 ml), 3 g de sel, 1 g de poivre et 10 g de persil.","note":"Estimation par portion ; la valeur de sodium inclut les 3 g de sel indiqués et toute l’huile est comptée même si une partie reste dans la poêle. On utilise la valeur USDA de la truite arc-en-ciel d’élevage ; la truite sauvage est plus maigre."},"seo":{"title":"Truite à l’ail et au citron à la poêle | Manual de Cocina","description":"Truite à l’ail et au citron : filets dorés à la poêle avec une sauce ail-citron. Pour 4 personnes, prête en 20 minutes. Pas à pas.","image_variants":["/recetas/receta-trucha-al-ajillo-con-limon/portada-1x1.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-4x3.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-16x9.webp"],"faq":[{"q":"Combien de temps cuire la truite à la poêle ?","a":"Environ 3 à 4 minutes de chaque côté, selon l’épaisseur, jusqu’à ce que le filet soit opaque et s’effeuille facilement."},{"q":"Comment éviter que l’ail brûle ?","a":"Préparez la sauce à feu moyen et ne cuisez le mélange ail-citron que 1 à 2 minutes. Un ail foncé rend la sauce amère."},{"q":"Avec quoi servir la truite à l’ail et au citron ?","a":"Avec du riz, des légumes ou de la salade. On la sert aussitôt, nappée de sauce et de persil frais."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"1de760ce-134c-5aab-a6ea-701c8fd5e0fb","recipe_group_id":"bfeac8bb-feaa-45be-b11f-dc89564a535d","language":"it","slug":"trota-aglio-e-limone","public_path":"/it/trota-aglio-e-limone","source_url":null,"title":"Trota all’aglio e limone","excerpt":"Filetti di trota dorati in padella e conditi con una salsa all’aglio e limone preparata nella stessa padella. Per 4 persone, pronta in 20 minuti.","summary":"La trota all’aglio e limone è un piatto veloce: filetti asciutti e conditi vengono dorati nell’olio d’oliva e completati con una salsa di aglio, succo e scorza di limone preparata nella stessa padella.\n\nSi serve subito con prezzemolo fresco, accompagnata da riso, verdure o insalata. Per 4 persone, pronta in circa 20 minuti.","category":"Secondi piatti","difficulty":"Facile","course":"Secondo piatto","cuisine":"Pesce","prep_time_minutes":10,"cook_time_minutes":10,"total_time_minutes":20,"servings":4,"keywords":["trota all’aglio e limone","trota all’aglio","ricetta trota","filetti di trota","pesce al limone e aglio","ricetta veloce di pesce"],"ingredients":[{"name":"filetti di trota (4 filetti da circa 150 g)","amount":"600","unit":"g","group":"Per il pesce"},{"name":"aglio, tritato","amount":"4","unit":"spicchi","group":"Per la salsa"},{"name":"limoni (succo e scorza)","amount":"2","unit":"pezzo","group":"Per la salsa"},{"name":"olio d’oliva","amount":"30","unit":"ml","group":"Per il pesce"},{"name":"sale","amount":"3","unit":"g","group":"Per il pesce"},{"name":"pepe nero","amount":"1","unit":"g","group":"Per il pesce"},{"name":"prezzemolo fresco, tritato","amount":"10","unit":"g","group":"Per finire"}],"steps":[{"title":"Asciuga e condisci la trota","content":"Asciuga 4 filetti di trota (circa 150 g ciascuno) con carta da cucina e condiscili con 3 g di sale e 1 g di pepe nero.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-01.webp","image_alt":"Trota all’aglio e limone: Asciuga e condisci la trota"},{"title":"Prepara il mix di aglio e limone","content":"Mescola il succo e la scorza di 2 limoni con 4 spicchi d’aglio tritati.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-02.webp","image_alt":"Trota all’aglio e limone: Prepara il mix di aglio e limone"},{"title":"Scalda l’olio","content":"Scalda 2 cucchiai di olio d’oliva (30 ml) in una padella ampia a fuoco medio-alto.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-03.webp","image_alt":"Trota all’aglio e limone: Scalda l’olio"},{"title":"Cuoci la trota","content":"Cuoci i filetti circa 3–4 minuti per lato, a seconda dello spessore, finché sono opachi e si sfaldano facilmente.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-04.webp","image_alt":"Trota all’aglio e limone: Cuoci la trota"},{"title":"Togli il pesce","content":"Trasferisci la trota su un piatto e lascia la padella sul fuoco medio.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-05.webp","image_alt":"Trota all’aglio e limone: Togli il pesce"},{"title":"Prepara la salsa","content":"Aggiungi nella padella il mix di aglio e limone e cuoci 1–2 minuti, senza far bruciare l’aglio.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-06.webp","image_alt":"Trota all’aglio e limone: Prepara la salsa"},{"title":"Versa e completa","content":"Versa la salsa sulla trota e completa con 10 g di prezzemolo fresco tritato.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-07.webp","image_alt":"Trota all’aglio e limone: Versa e completa"},{"title":"Servi","content":"Servi subito con riso, verdure o insalata.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-08.webp","image_alt":"Trota all’aglio e limone: Servi"}],"image_url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","gallery":[{"url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","alt":"Trota all’aglio e limone"}],"notes":"Asciuga bene il pesce prima di condirlo, così si rosola invece di cuocere al vapore. Non lasciare scurire l’aglio: l’aglio bruciato rende amara la salsa; se la padella è molto calda, abbassa il fuoco prima di aggiungere il mix. I pesi di sale e pepe sono indicativi; regola a gusto. Contiene pesce; passa le dita sui filetti per controllare le lische.","nutrition":{"calories":281,"protein_g":30.3,"carbs_g":3,"fat_g":16.1,"sodium_mg":371,"serving_size":"1 filetto con salsa (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per il peso degli ingredienti e divisi per 4. Si usano 600 g di trota, 12 g di aglio (4 spicchi), 62 g di succo e 6 g di scorza di 2 limoni, 27 g di olio (30 ml), 3 g di sale, 1 g di pepe e 10 g di prezzemolo.","note":"Stima per porzione; il valore del sodio include i 3 g di sale indicati e tutto l’olio è conteggiato anche se una parte resta nella padella. Si usa il valore USDA della trota iridea d’allevamento; la trota selvatica è più magra."},"seo":{"title":"Trota all’aglio e limone in padella | Manual de Cocina","description":"Trota all’aglio e limone: filetti dorati in padella con salsa all’aglio e limone. Per 4 persone, pronta in 20 minuti. Passo passo.","image_variants":["/recetas/receta-trucha-al-ajillo-con-limon/portada-1x1.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-4x3.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-16x9.webp"],"faq":[{"q":"Quanto va cotta la trota in padella?","a":"Circa 3–4 minuti per lato, a seconda dello spessore, finché il filetto è opaco e si sfalda facilmente."},{"q":"Come evito che l’aglio bruci?","a":"Prepara la salsa a fuoco medio e cuoci il mix di aglio e limone solo 1–2 minuti. L’aglio scuro rende amara la salsa."},{"q":"Con cosa si serve la trota all’aglio e limone?","a":"Con riso, verdure o insalata. Si serve subito, con la salsa sopra e prezzemolo fresco."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"0b4f0f66-dbf8-521e-b75c-dd8cd48562a3","recipe_group_id":"bfeac8bb-feaa-45be-b11f-dc89564a535d","language":"ja","slug":"マスのガーリックレモンソテー","public_path":"/ja/マスのガーリックレモンソテー","source_url":null,"title":"マスのガーリックレモンソテー","excerpt":"フライパンで焼いたマスの切り身に、同じフライパンで作るガーリックレモンソースをかけます。4人分、約20分で完成。","summary":"マスのガーリックレモンソテーは手早く作れる一品です。水気をふいて味つけした切り身をオリーブオイルで焼き、同じフライパンでにんにく、レモン汁、レモンの皮のソースを作って仕上げます。\n\nフレッシュパセリを散らしてすぐに、ごはん、野菜、サラダなどと一緒にどうぞ。4人分で、約20分でできます。","category":"主菜","difficulty":"簡単","course":"主菜","cuisine":"魚料理","prep_time_minutes":10,"cook_time_minutes":10,"total_time_minutes":20,"servings":4,"keywords":["マスのガーリックレモンソテー","マスのガーリック焼き","マスの切り身 レシピ","マスのソテー","レモンとにんにくの魚料理","簡単な魚のレシピ"],"ingredients":[{"name":"マスの切り身（約150 gを4切れ）","amount":"600","unit":"g","group":"魚の材料"},{"name":"にんにく（みじん切り）","amount":"4","unit":"片","group":"ソースの材料"},{"name":"レモン（果汁と皮）","amount":"2","unit":"個","group":"ソースの材料"},{"name":"オリーブオイル","amount":"30","unit":"ml","group":"魚の材料"},{"name":"塩","amount":"3","unit":"g","group":"魚の材料"},{"name":"黒こしょう","amount":"1","unit":"g","group":"魚の材料"},{"name":"フレッシュパセリ（みじん切り）","amount":"10","unit":"g","group":"仕上げ用"}],"steps":[{"title":"マスの水気をふいて味つけする","content":"マスの切り身4切れ（各約150 g）をキッチンペーパーで水気をふき、塩3 gと黒こしょう1 gで味つけします。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-01.webp","image_alt":"マスのガーリックレモンソテー: マスの水気をふいて味つけする"},{"title":"にんにくとレモンを混ぜる","content":"レモン2個分の果汁と皮を、みじん切りにしたにんにく4片と混ぜ合わせます。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-02.webp","image_alt":"マスのガーリックレモンソテー: にんにくとレモンを混ぜる"},{"title":"オイルを熱する","content":"大きめのフライパンにオリーブオイル大さじ2（30 ml）を入れ、中強火で熱します。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-03.webp","image_alt":"マスのガーリックレモンソテー: オイルを熱する"},{"title":"マスを焼く","content":"切り身を厚さに応じて片面3〜4分ずつ、身が白く不透明になり、ほぐれやすくなるまで焼きます。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-04.webp","image_alt":"マスのガーリックレモンソテー: マスを焼く"},{"title":"魚を取り出す","content":"マスを皿に移し、フライパンは中火のままにします。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-05.webp","image_alt":"マスのガーリックレモンソテー: 魚を取り出す"},{"title":"ソースを作る","content":"フライパンににんにくとレモンの混ぜたものを加え、にんにくを焦がさないように1〜2分加熱します。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-06.webp","image_alt":"マスのガーリックレモンソテー: ソースを作る"},{"title":"かけて仕上げる","content":"ソースをマスにかけ、刻んだフレッシュパセリ10 gを散らして仕上げます。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-07.webp","image_alt":"マスのガーリックレモンソテー: かけて仕上げる"},{"title":"盛りつける","content":"すぐに、ごはん、野菜、サラダなどと一緒にいただきます。","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-08.webp","image_alt":"マスのガーリックレモンソテー: 盛りつける"}],"image_url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","gallery":[{"url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","alt":"マスのガーリックレモンソテー"}],"notes":"味つけの前に魚の水気をしっかりふくと、蒸れずにこんがり焼けます。にんにくは色づけすぎないでください。焦げるとソースが苦くなるので、フライパンが熱すぎる場合は火を弱めてから加えます。塩とこしょうの量は目安なので、お好みで調整してください。魚を含みます。切り身を指でなぞって小骨がないか確認しましょう。","nutrition":{"calories":281,"protein_g":30.3,"carbs_g":3,"fat_g":16.1,"sodium_mg":371,"serving_size":"1切れ（ソースつき、レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100 gあたりの栄養素に材料の重量をかけ、4で割った合計です。マス600 g、にんにく12 g（4片）、レモン2個分の果汁62 gと皮6 g、オイル27 g（30 ml）、塩3 g、こしょう1 g、パセリ10 gを使用しています。","note":"1人分の目安です。ナトリウムには記載の塩3 gを含み、オイルはフライパンに残る分も含めて全量を計算しています。USDAの養殖ニジマスの値を使用しており、天然のマスはより脂肪が少なめです。"},"seo":{"title":"マスのガーリックレモンソテー｜フライパンで簡単 | Manual de Cocina","description":"マスのガーリックレモンソテー。フライパンで焼いた切り身に、にんにくとレモンのソースをかけます。4人分、約20分。手順つき。","image_variants":["/recetas/receta-trucha-al-ajillo-con-limon/portada-1x1.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-4x3.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-16x9.webp"],"faq":[{"q":"マスはフライパンでどのくらい焼きますか？","a":"厚さにもよりますが、片面3〜4分ずつ、身が白く不透明になり、ほぐれやすくなるまで焼きます。"},{"q":"にんにくを焦がさないコツは？","a":"ソースは中火で作り、にんにくとレモンの混ぜたものは1〜2分だけ加熱します。色が濃くなるとソースが苦くなります。"},{"q":"何を添えるとよいですか？","a":"ごはん、野菜、サラダがよく合います。ソースをかけ、フレッシュパセリを散らして、すぐにいただきます。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"e2436db7-29fb-5891-ba6e-12cf3ba123f6","recipe_group_id":"bfeac8bb-feaa-45be-b11f-dc89564a535d","language":"pt","slug":"truta-ao-alho-e-limao","public_path":"/pt/truta-ao-alho-e-limao","source_url":null,"title":"Truta ao alho e limão","excerpt":"Filés de truta dourados na frigideira e banhados com um molho de alho e limão feito na mesma frigideira. Rende 4 porções e fica pronta em 20 minutos.","summary":"A truta ao alho e limão é um prato rápido: filés secos e temperados são dourados no azeite e finalizados com um molho de alho, suco e raspas de limão feito na mesma frigideira.\n\nSirva imediatamente com salsinha fresca, acompanhada de arroz, legumes ou salada. Rende 4 porções e fica pronta em cerca de 20 minutos.","category":"Pratos principais","difficulty":"Fácil","course":"Prato principal","cuisine":"Peixes","prep_time_minutes":10,"cook_time_minutes":10,"total_time_minutes":20,"servings":4,"keywords":["truta ao alho e limão","truta ao alho","receita de truta","filé de truta","peixe com limão e alho","receita rápida de peixe"],"ingredients":[{"name":"filés de truta (4 filés de cerca de 150 g)","amount":"600","unit":"g","group":"Para o peixe"},{"name":"alho, picado","amount":"4","unit":"dentes","group":"Para o molho"},{"name":"limões (suco e raspas)","amount":"2","unit":"unidade","group":"Para o molho"},{"name":"azeite de oliva","amount":"30","unit":"ml","group":"Para o peixe"},{"name":"sal","amount":"3","unit":"g","group":"Para o peixe"},{"name":"pimenta-do-reino","amount":"1","unit":"g","group":"Para o peixe"},{"name":"salsinha fresca, picada","amount":"10","unit":"g","group":"Para finalizar"}],"steps":[{"title":"Seque e tempere a truta","content":"Seque 4 filés de truta (cerca de 150 g cada) com papel-toalha e tempere com 3 g de sal e 1 g de pimenta-do-reino.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-01.webp","image_alt":"Truta ao alho e limão: Seque e tempere a truta"},{"title":"Prepare a mistura de alho e limão","content":"Misture o suco e as raspas de 2 limões com 4 dentes de alho picados.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-02.webp","image_alt":"Truta ao alho e limão: Prepare a mistura de alho e limão"},{"title":"Aqueça o azeite","content":"Aqueça 2 colheres de sopa de azeite (30 ml) em uma frigideira grande em fogo médio-alto.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-03.webp","image_alt":"Truta ao alho e limão: Aqueça o azeite"},{"title":"Cozinhe a truta","content":"Cozinhe os filés por cerca de 3–4 minutos de cada lado, conforme a espessura, até ficarem opacos e se desfiarem com facilidade.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-04.webp","image_alt":"Truta ao alho e limão: Cozinhe a truta"},{"title":"Retire o peixe","content":"Passe a truta para um prato e mantenha a frigideira em fogo médio.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-05.webp","image_alt":"Truta ao alho e limão: Retire o peixe"},{"title":"Faça o molho","content":"Junte à frigideira a mistura de alho e limão e cozinhe por 1–2 minutos, sem deixar o alho queimar.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-06.webp","image_alt":"Truta ao alho e limão: Faça o molho"},{"title":"Regue e finalize","content":"Despeje o molho sobre a truta e finalize com 10 g de salsinha fresca picada.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-07.webp","image_alt":"Truta ao alho e limão: Regue e finalize"},{"title":"Sirva","content":"Sirva imediatamente com arroz, legumes ou salada.","image_url":"/recetas/receta-trucha-al-ajillo-con-limon/paso-08.webp","image_alt":"Truta ao alho e limão: Sirva"}],"image_url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","gallery":[{"url":"/recetas/receta-trucha-al-ajillo-con-limon/portada.webp","alt":"Truta ao alho e limão"}],"notes":"Seque bem o peixe antes de temperar para que doure em vez de cozinhar no vapor. Não deixe o alho escurecer: alho queimado amarga o molho; se a frigideira estiver muito quente, baixe o fogo antes de juntar a mistura. Os pesos de sal e pimenta são orientativos; ajuste ao gosto. Contém peixe; passe os dedos pelos filés para conferir se há espinhas.","nutrition":{"calories":281,"protein_g":30.3,"carbs_g":3,"fat_g":16.1,"sodium_mg":371,"serving_size":"1 filé com molho (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4. Usa 600 g de truta, 12 g de alho (4 dentes), 62 g de suco e 6 g de raspas de 2 limões, 27 g de azeite (30 ml), 3 g de sal, 1 g de pimenta e 10 g de salsinha.","note":"Estimativa por porção; o valor de sódio inclui os 3 g de sal indicados e todo o azeite é contado, ainda que parte fique na frigideira. Usa-se o valor do USDA para truta arco-íris de cultivo; a truta selvagem é mais magra."},"seo":{"title":"Truta ao alho e limão na frigideira | Manual de Cocina","description":"Truta ao alho e limão: filés dourados na frigideira com molho de alho e limão. Rende 4 porções, pronta em 20 minutos. Passo a passo.","image_variants":["/recetas/receta-trucha-al-ajillo-con-limon/portada-1x1.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-4x3.webp","/recetas/receta-trucha-al-ajillo-con-limon/portada-16x9.webp"],"faq":[{"q":"Quanto tempo cozinhar a truta na frigideira?","a":"Cerca de 3–4 minutos de cada lado, conforme a espessura, até o filé ficar opaco e se desfiar com facilidade."},{"q":"Como evitar que o alho queime?","a":"Faça o molho em fogo médio e cozinhe a mistura de alho e limão por apenas 1–2 minutos. Alho escuro amarga o molho."},{"q":"Com o que servir a truta ao alho e limão?","a":"Com arroz, legumes ou salada. Sirva imediatamente, com o molho por cima e salsinha fresca."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-trucha-al-ajillo-con-limon') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
